mapper.select:
select
  (select count(*) from article_like where user_id = #{userId}) as likeCount,
  (select count(*) from article_collect where user_id = #{userId}) as collectCount,
  (select max(tmax) from (
    select max(create_time) as tmax from article_like where user_id = #{userId}
    union all
    select max(create_time) as tmax from article_collect where user_id = #{userId}
  ) t) as lastActionTime
